const mapMappingsBySourceMapFile = new Map(
  referenceLocalProjectMapMappingEntries.map((mapping) => [
    mapping.sourceMapFile,
    mapping,
  ]),
);
const catalogMappingsByContextAndSourceId = new Map(
  referenceLocalProjectCatalogMappingEntries.map((mapping) => [
    createCatalogMappingKey(mapping.context, mapping.sourceId),
    mapping,
  ]),
);

export function getReferenceLocalProjectMapMapping(
  sourceMapFile: string,
): ReferenceLocalProjectMapMapping {
  const mapping = findReferenceLocalProjectMapMapping(sourceMapFile);

  if (mapping === undefined) {
    throw new Error(
      `Unknown frozen source mapFile ${JSON.stringify(sourceMapFile)}.`,
    );
  }

  return mapping;
}

export function findReferenceLocalProjectMapMapping(
  sourceMapFile: string,
): ReferenceLocalProjectMapMapping | undefined {
  return mapMappingsBySourceMapFile.get(sourceMapFile);
}

export function getReferenceLocalProjectCatalogMapping(
  context: ReferenceLocalProjectCatalogContext,
  sourceId: string,
): ReferenceLocalProjectCatalogMapping {
  const mapping = findReferenceLocalProjectCatalogMapping(context, sourceId);

  if (mapping === undefined) {
    throw new Error(
      `Unknown frozen ${context} source ID ${JSON.stringify(sourceId)}.`,
    );
  }

  return mapping;
}

export function findReferenceLocalProjectCatalogMapping(
  context: ReferenceLocalProjectCatalogContext,
  sourceId: string,
): ReferenceLocalProjectCatalogMapping | undefined {
  return catalogMappingsByContextAndSourceId.get(
    createCatalogMappingKey(context, sourceId),
  );
}

function createCatalogMappingKey(
  context: ReferenceLocalProjectCatalogContext,
  sourceId: string,
): string {
  return `${context}\u0000${sourceId}`;
}
